"""Interactive, self-contained placed-triangle density inspection."""
import json,sys
from pathlib import Path
import matplotlib


def main():
    out=Path(sys.argv[1]);data=json.loads((out/'density.json').read_text())
    palette=matplotlib.colormaps['inferno']
    data['palette']=['#'+''.join(f'{round(x*255):02x}' for x in palette(i/255)[:3]) for i in range(256)]
    template='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>
body{margin:0;font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#17202f)}h3{font-size:17px;margin:14px 0 8px}p{margin:8px 0}.note{font-size:12px;color:var(--muted-foreground,#667085)}nav{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:12px 0}select{padding:7px;font:inherit;color:inherit;background:var(--background,white);border:1px solid var(--border,#aaa);border-radius:5px}canvas{width:100%;height:auto;display:block;touch-action:manipulation}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td{padding:4px 0;border-bottom:1px solid var(--border,#ddd)}td:last-child{text-align:right}#total{font-size:22px;font-weight:650}.legend{height:10px;border-radius:3px;margin-top:5px;background:linear-gradient(to right,#000004,#420a68,#932667,#dd513a,#fca50a,#fcffa4)}.ends{display:flex;justify-content:space-between;font-size:12px}.details{min-height:145px}code{font:12px var(--font-mono,monospace)}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:550px){.two{grid-template-columns:1fr}.details{min-height:120px}}
</style></head><body><h3>Placed terrain triangle concentration</h3><p class="note">74 definitions · 82 placements · 0.5 × 0.5 m cells. Terrain and four grilles; major equipment excluded. Native meshing is 0.4 mm / 0.25 rad. The 16-section road remesh remains pending.</p><nav><select id="revision" aria-label="Geometry"><option value="candidate">Approved wall fills</option><option value="native">Native baseline</option></select><select id="channel" aria-label="Channel"><option value="visual">Visual</option><option value="collision">Collision</option></select><label><input type="checkbox" id="roads" checked> Include road groups</label></nav><div><span id="total"></span> placed triangles <span class="note" id="share"></span></div><canvas id="map" width="1000" height="620" aria-label="Triangle density heatmap"></canvas><div class="legend"></div><div class="ends"><span>1 triangle / cell</span><span>Logarithmic color scale · same across filters</span><span id="maximum"></span></div><p class="note">Hover or tap a cell to identify its contributors. Field-centered CAD axes in metres. Counts include repeated, vertical and hidden triangles; this measures centroid concentration, not covered area or GPU overdraw.</p><div class="two"><section class="details"><h3 id="celltitle">Cell contributors</h3><table id="cell"></table></section><section><h3>Largest selected components</h3><table id="rank"></table></section></div><p><b>Assessment:</b> outside the road groups, the current collision selection is 51,680 triangles. Its sharpest hotspots are two tiny central-deck detail clusters: 4,637 triangles each within two 0.5 m cells.</p><p class="note">The road groups contain 76.8% of visual triangles. Separate road-border/vector experiments are not substituted here. Embedded artwork retains its backing triangles in collision. This is a source-derived inspection view, not a measurement of the installed runtime.</p><script>
const D=__DATA__;
const W=D.shape_yx[1],H=D.shape_yx[0],N=W*H,canvas=document.getElementById('map'),ctx=canvas.getContext('2d'),fmt=n=>n.toLocaleString();
for(const c of D.components)for(const rev of ['native','candidate']){const a=new Uint32Array(N);for(const [i,n] of c[rev+'_grid'])a[i]=n;c[rev]=a}
const globalMax=Math.max(...Array.from({length:N},(_,i)=>D.components.reduce((n,c)=>n+c.native[i],0)));document.getElementById('maximum').textContent=fmt(globalMax)+' / cell';
let selected=[],counts,revision='candidate',chosen=-1;
function rows(items){return items.map(([name,n])=>`<tr><td>${name}</td><td>${fmt(n)}</td></tr>`).join('')}
function at(i){if(i<0||i>=N)return;chosen=i;const x=i%W,y=Math.floor(i/W);document.getElementById('celltitle').textContent=`Cell (${(D.lower_m[0]+(x+.5)*.5).toFixed(2)}, ${(D.lower_m[1]+(y+.5)*.5).toFixed(2)}) · ${fmt(counts[i])}`;document.getElementById('cell').innerHTML=rows(selected.map(c=>[c.id,c[revision][i]]).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]).slice(0,5));paint()}
const box={x:54,y:20,w:920,h:539.31};
function paint(){ctx.clearRect(0,0,1000,620);ctx.fillStyle='#e9eef3';ctx.fillRect(box.x,box.y,box.w,box.h);const cw=box.w/W,ch=box.h/H;for(let y=0;y<H;y++)for(let x=0;x<W;x++){const value=counts[y*W+x];if(!value)continue;ctx.fillStyle=D.palette[Math.round(Math.log(value)/Math.log(globalMax)*255)];ctx.fillRect(box.x+x*cw,box.y+(H-1-y)*ch,cw+.1,ch+.1)}ctx.strokeStyle='#7b8795';ctx.lineWidth=1;ctx.strokeRect(box.x,box.y,box.w,box.h);ctx.font='16px system-ui';ctx.fillStyle='#7b8795';ctx.textAlign='center';for(let x=-10;x<=10;x+=5){const px=box.x+(x-D.lower_m[0])/(D.upper_m[0]-D.lower_m[0])*box.w;ctx.fillText(x,px,box.y+box.h+25)}for(let y=-8;y<=8;y+=2){const py=box.y+(D.upper_m[1]-y)/(D.upper_m[1]-D.lower_m[1])*box.h;ctx.fillText(y,28,py+5)}ctx.fillText('CAD x (m) · field center = (0, 0)',box.x+box.w/2,603);if(chosen>=0){const x=chosen%W,y=Math.floor(chosen/W);ctx.strokeStyle='#37d8f0';ctx.lineWidth=3;ctx.strokeRect(box.x+x*cw,box.y+(H-1-y)*ch,cw,ch)}}
function update(){revision=document.getElementById('revision').value;const collision=document.getElementById('channel').value==='collision',roads=document.getElementById('roads').checked;selected=D.components.filter(c=>(!collision||c.collision)&&(roads||!c.road));counts=new Uint32Array(N);for(const c of selected)for(let i=0;i<N;i++)counts[i]+=c[revision][i];const total=counts.reduce((a,b)=>a+b,0);console.assert(total===selected.reduce((s,c)=>s+c[revision+'_triangles'],0),'Every placed triangle counted');document.getElementById('total').textContent=fmt(total);document.getElementById('share').textContent=`· peak ${fmt(Math.max(...counts))} / cell`;document.getElementById('rank').innerHTML=rows(selected.map(c=>[c.id,c[revision+'_triangles']]).sort((a,b)=>b[1]-a[1]).slice(0,5));at(counts.indexOf(Math.max(...counts)))}
for(const id of ['revision','channel','roads'])document.getElementById(id).addEventListener('change',update);
function pick(event){const r=canvas.getBoundingClientRect(),x=(event.clientX-r.left)/r.width*1000,y=(event.clientY-r.top)/r.height*620;if(x<box.x||x>=box.x+box.w||y<box.y||y>=box.y+box.h)return;at((H-1-Math.floor((y-box.y)/box.h*H))*W+Math.floor((x-box.x)/box.w*W))}canvas.addEventListener('pointermove',pick);canvas.addEventListener('click',pick);update();console.log('Density grids validated:',D.components.length,'definitions;',D.components.reduce((n,c)=>n+c.placed_uses,0),'placed uses.');
</script></body></html>'''
    (out/'review.html').write_text(template.replace('__DATA__',json.dumps(data,separators=(',',':'))));print(out/'review.html')
if __name__=='__main__':main()
